use super::*;
#[derive(Default)] pub(super) struct GameplayUi {pub paint:bool,pub erase:bool,pub solid:bool,pub layer:i32,pub asset:String,pub link:Option<usize>,pub positions:HashMap<(Uuid,usize),egui::Vec2>}
pub(super) fn material(ui:&mut egui::Ui,o:&mut Object,uk:bool){ui.collapsing(tr(uk,"Фізичні параметри","Physics material"),|ui|{ui.add(egui::DragValue::new(&mut o.material.gravity_scale).range(0. ..=10.).prefix("Gravity × "));ui.add(egui::DragValue::new(&mut o.material.speed).range(0. ..=2000.).prefix("Speed "));ui.add(egui::DragValue::new(&mut o.material.jump_speed).range(0. ..=2000.).prefix("Jump "));ui.add(egui::Slider::new(&mut o.material.restitution,0. ..=1.).text("Bounce"));});}
pub(super) fn tiles(ui:&mut egui::Ui,e:&mut Editor){let uk=e.uk;let g=&mut e.gameplay;ui.horizontal_wrapped(|ui|{ui.checkbox(&mut g.paint,tr(uk,"Малювати у сцені","Paint in scene"));ui.checkbox(&mut g.erase,tr(uk,"Гумка","Eraser"));ui.checkbox(&mut g.solid,tr(uk,"Колізія","Solid"));ui.add(egui::DragValue::new(&mut g.layer).prefix("Layer "));});ui.label(tr(uk,"Шлях PNG від кореня проєкту (порожній = білий тайл)","PNG path relative to project (empty = white tile)"));ui.text_edit_singleline(&mut g.asset);ui.label(tr(uk,"ЛКМ / перетягування — малювання. Розмір = крок сітки. Ізометрія використовує координати сцени.","LMB / drag to paint. Size = grid step. Isometric mode uses world coordinates."));}
pub(super) fn paint(e:&mut Editor,pos:[f32;2]){let g=&e.gameplay;let grid=e.tools.snap.round().clamp(1.,512.) as u32;let cell=pos.map(|x|(x/grid as f32).round() as i32);if g.erase{forge_engine::erase_tile(&mut e.project,cell,grid,g.layer);}else{let sprite=if g.asset.is_empty(){None}else{if !g.asset.starts_with("assets/")||std::path::Path::new(&g.asset).components().any(|c|!matches!(c,std::path::Component::Normal(_))){e.status="Invalid tile asset path".into();return;}Some(g.asset.clone())};forge_engine::paint_tile(&mut e.project,cell,grid,g.layer,sprite,g.solid);}}
pub(super) fn graph(ui:&mut egui::Ui,o:&mut Object,g:&mut GameplayUi){ui.horizontal_wrapped(|ui|{for n in [NodeKind::Update,NodeKind::Trigger,NodeKind::IfRight,NodeKind::IfJump,NodeKind::MoveRight,NodeKind::MoveLeft,NodeKind::MoveUp,NodeKind::MoveDown,NodeKind::Jump]{if ui.small_button(format!("+ {n:?}")).clicked()&&o.graph.nodes.len()<128{o.graph.nodes.push(n);}}if ui.button("Clear").clicked(){o.graph=Default::default();g.positions.retain(|(id,_),_|*id!=o.id);g.link=None;}});ui.label("Click OUT then IN to toggle link · drag node header · conditions gate outgoing edges");let size=egui::vec2(ui.available_width().max(300.),(ui.available_height()-5.).max(150.));let (rect,_)=ui.allocate_exact_size(size,egui::Sense::hover());let painter=ui.painter_at(rect);painter.rect_filled(rect,4.,egui::Color32::from_gray(20));let mut rects=vec![];for i in 0..o.graph.nodes.len(){let p=g.positions.entry((o.id,i)).or_insert_with(||egui::vec2(12.+(i%4) as f32*145.,12.+(i/4) as f32*70.));let r=egui::Rect::from_min_size(rect.min+*p,egui::vec2(130.,52.));rects.push(r);}for [a,b] in &o.graph.edges{if let (Some(a),Some(b))=(rects.get(*a),rects.get(*b)){painter.line_segment([a.right_center()+egui::vec2(0.,12.),b.left_center()+egui::vec2(0.,12.)],egui::Stroke::new(2.,egui::Color32::LIGHT_BLUE));}}for (i,r) in rects.into_iter().enumerate(){let header=egui::Rect::from_min_max(r.min,egui::pos2(r.right(),r.top()+25.));let response=ui.interact(header,ui.id().with((o.id,i,"drag")),egui::Sense::drag());if response.dragged(){if let Some(p)=g.positions.get_mut(&(o.id,i)){*p+=ui.input(|i|i.pointer.delta());}}painter.rect_filled(r,4.,egui::Color32::from_gray(50));painter.text(header.center(),egui::Align2::CENTER_CENTER,format!("{:?}",o.graph.nodes[i]),egui::FontId::proportional(12.),egui::Color32::WHITE);for (out,p) in [(false,r.left_center()),(true,r.right_center())]{let p=p+egui::vec2(0.,12.);let hit=ui.interact(egui::Rect::from_center_size(p,egui::vec2(22.,22.)),ui.id().with((o.id,i,out)),egui::Sense::click());painter.circle_filled(p,6.,if out&&g.link==Some(i){egui::Color32::YELLOW}else{egui::Color32::LIGHT_BLUE});if hit.clicked(){if out{g.link=Some(i);}else if let Some(a)=g.link.take(){if a!=i&&a<o.graph.nodes.len(){let edge=[a,i];if o.graph.edges.contains(&edge){o.graph.edges.retain(|e|*e!=edge);}else{o.graph.edges.push(edge);}}}}}}}
